cat > /app/output/kin.py <<'PY'
import sys
sys.path.insert(0,'/opt/tools')
import rcb_dtb, mujoco, numpy as np
from scipy.spatial.transform import Rotation
class Controller:
 def __init__(self,s):
  self.s=s;self.m=s.model;self.d=s.data;self.k=mujoco.MjData(self.m)
  self.bid=self.m.body('palmleft_hand_C_MC').id
  self.jq=s._jq;self.jv=s._jv
 def pose(self,d=None):
  d=self.d if d is None else d
  return d.xpos[self.bid].copy(),d.xmat[self.bid].reshape(3,3).copy()
 def ik(self,pos,rot,q=None,hand=None):
  if q is None:q=self.d.qpos[self.jq].copy()
  q=q.copy();
  if hand is not None:q[7:]=hand
  self.k.qpos[:]=self.d.qpos
  jp=np.zeros((3,self.m.nv));jr=jp.copy()
  for _ in range(100):
   self.k.qpos[self.jq]=q;mujoco.mj_forward(self.m,self.k)
   p,R=self.pose(self.k);e=np.r_[pos-p,Rotation.from_matrix(rot@R.T).as_rotvec()]
   if np.linalg.norm(e[:3])<1e-5 and np.linalg.norm(e[3:])<1e-4:break
   mujoco.mj_jacBody(self.m,self.k,jp,jr,self.bid)
   J=np.vstack([jp[:,self.jv[:7]],jr[:,self.jv[:7]]]);dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*1e-5,e)
   dq=np.clip(dq,-.15,.15)
   q[:7]=np.clip(q[:7]+dq,self.s.lower[:7]+1e-5,self.s.upper[:7]-1e-5)
  return q
 def move(self,p,R,hand=None,n=120):
  p0,R0=self.pose(); h0=self.s.targets[7:].copy();hand=h0 if hand is None else hand
  delta=Rotation.from_matrix(R@R0.T).as_rotvec()
  for t in range(n):
   a=(t+1)/n;a=a*a*(3-2*a)
   pt=p0+(p-p0)*a;Rt=Rotation.from_rotvec(delta*a).as_matrix()@R0
   q=self.ik(pt,Rt,q=self.s.targets,hand=h0+(hand-h0)*a)
   self.s.step(q)
 def hold(self,n=60):
  for _ in range(n): self.s.step(self.s.targets)
 def contacts(self):
  ans=[]
  for c in self.d.contact:
   b1=self.m.geom_bodyid[c.geom1];b2=self.m.geom_bodyid[c.geom2]
   if self.s._obj in (b1,b2):
    ans.append((self.m.geom(c.geom1).name,self.m.geom(c.geom2).name,round(c.dist,4)))
  return ans
if __name__=='__main__':
 s=rcb_dtb.Session();c=Controller(s);np.set_printoptions(precision=3,suppress=True)
 for h in [np.zeros(22),np.array([1,0,.5,0,.7]+[.8,0,1,.7]*3+[0,.8,0,1,.7])]:
  c.k.qpos[:]=s.data.qpos;c.k.qpos[c.jq[7:]]=h;mujoco.mj_forward(c.m,c.k)
  p,R=c.pose(c.k);print('HAND',h)
  for f in ['thumb','index','middle','ring','pinky']:
   b=c.m.body('palmleft_'+f+'_DP').id
   print(f,'DP',R.T@(c.k.xpos[b]-p))
   g=c.m.geom('palmleft_'+f+'_elastomer').id
   print(' pad ',R.T@(c.k.geom_xpos[g]-p))
PY
