from kin import *
from scipy.optimize import least_squares
s=rcb_dtb.Session();c=Controller(s);np.set_printoptions(precision=3,suppress=True)
for _ in range(150):s.step(s.targets)
op=s.data.xpos[s._obj].copy();Ro=s.data.xmat[s._obj].reshape(3,3).copy()
Rs=np.array([[0,1,0],[0,0,-1],[-1,0,0.]])
q0=rcb_dtb.INIT_Q[:7];rng=np.random.default_rng(42)
def solve(p,R):
 def fun(q):
  c.k.qpos[:]=s.data.qpos;c.k.qpos[c.jq[:7]]=q;mujoco.mj_forward(s.model,c.k);pp,RR=c.pose(c.k)
  return np.r_[p-pp,Rotation.from_matrix(R@RR.T).as_rotvec()*.2]
 best=None
 for i in range(4):
  seed=q0 if i==0 else rng.uniform(s.lower[:7]*.9,s.upper[:7]*.9)
  res=least_squares(fun,seed,bounds=(s.lower[:7]+.001,s.upper[:7]-.001),max_nfev=150,ftol=1e-7)
  if best is None or np.linalg.norm(res.fun)<np.linalg.norm(best.fun):best=res
  if np.linalg.norm(best.fun)<1e-5:break
 return best
for yaw in [0,1,1.57,2,2.5,3.14]:
 for tilt in [-.8,-.4,0,.4,.8]:
  R=Rotation.from_euler('z',yaw).as_matrix()@Rotation.from_euler('x',tilt).as_matrix()@Rs
  p=op+Ro[:,0]*.12+Ro[:,2]*.02-R@np.array([.06,-.005,.13])
  res=solve(p,R);print(yaw,tilt,'err',round(np.linalg.norm(res.fun),4),'p',p.round(3),'q',res.x.round(2),flush=True)
  if np.linalg.norm(res.fun)<1e-4:np.savez('/app/output/ik_yaw'+str(yaw)+'_tilt'+str(tilt)+'.npz',q=res.x,p=p,R=R)
